+use super::geometry::Point;
+use super::node::{Node, NodeId};
+
+pub fn earcut(points: &[Point]) -> Vec<u32> {
+    let mut triangulator = Triangulator::new();
+    triangulator.triangulate(points)
+}
+
+struct Triangulator {
+    nodes: Vec<Node>,
+    triangles: Vec<u32>,
+}
+
+impl Triangulator {
+    fn new() -> Self {
+        Self {
+            nodes: Vec::new(),
+            triangles: Vec::new(),
+        }
+    }
+
+    fn triangulate(&mut self, points: &[Point]) -> Vec<u32> {
+        if points.len() < 3 {
+            return Vec::new();
+        }
+
+        let Some(outer_node) = self.linked_list(points, true) else {
+            return Vec::new();
+        };
+
+        if self.nodes[outer_node].prev == self.nodes[outer_node].next {
+            return Vec::new();
+        }
+
+        let mut min_x = 0.0;
+        let mut min_y = 0.0;
+        let mut inv_size = 0.0;
+
+        if points.len() > 40 {
+            min_x = points[0].x;
+            min_y = points[0].y;
+            let mut max_x = min_x;
+            let mut max_y = min_y;
+
+            for point in points.iter().copied().skip(1) {
+                min_x = min_x.min(point.x);
+                min_y = min_y.min(point.y);
+                max_x = max_x.max(point.x);
+                max_y = max_y.max(point.y);
+            }
+
+            let size = (max_x - min_x).max(max_y - min_y);
+            if size != 0.0 {
+                inv_size = 1.0 / size;
+            }
+        }
+
+        self.earcut_linked(Some(outer_node), 0, min_x, min_y, inv_size);
+        std::mem::take(&mut self.triangles)
+    }
+
+    fn linked_list(&mut self, points: &[Point], clockwise: bool) -> Option<NodeId> {
+        let mut last = None;
+
+        if clockwise == (signed_area(points) > 0.0) {
+            for (index, point) in points.iter().copied().enumerate() {
+                last = Some(self.insert_node(index, point.x, point.y, last));
+            }
+        } else {
+            for index in (0..points.len()).rev() {
+                let point = points[index];
+                last = Some(self.insert_node(index, point.x, point.y, last));
+            }
+        }
+
+        let last = last?;
+        let next = self.nodes[last].next;
+        if self.equals(last, next) {
+            self.remove_node(last);
+            return Some(next);
+        }
+
+        Some(last)
+    }
+
+    fn insert_node(&mut self, i: usize, x: f64, y: f64, last: Option<NodeId>) -> NodeId {
+        let node_id = self.nodes.len();
+
+        match last {
+            Some(last_id) => {
+                let next_id = self.nodes[last_id].next;
+                self.nodes.push(Node::new(i, x, y, last_id, next_id));
+                self.nodes[next_id].prev = node_id;
+                self.nodes[last_id].next = node_id;
+            }
+            None => {
+                self.nodes.push(Node::new(i, x, y, node_id, node_id));
+            }
+        }
+
+        node_id
+    }
+
+    fn remove_node(&mut self, node: NodeId) {
+        let prev = self.nodes[node].prev;
+        let next = self.nodes[node].next;
+        self.nodes[prev].next = next;
+        self.nodes[next].prev = prev;
+
+        if let Some(prev_z) = self.nodes[node].prev_z {
+            self.nodes[prev_z].next_z = self.nodes[node].next_z;
+        }
+        if let Some(next_z) = self.nodes[node].next_z {
+            self.nodes[next_z].prev_z = self.nodes[node].prev_z;
+        }
+    }
+
+    fn earcut_linked(
+        &mut self,
+        ear: Option<NodeId>,
+        pass: u8,
+        min_x: f64,
+        min_y: f64,
+        inv_size: f64,
+    ) {
+        let Some(mut ear) = ear else {
+            return;
+        };
+
+        if pass == 0 && inv_size != 0.0 {
+            self.index_curve(ear, min_x, min_y, inv_size);
+        }
+
+        let mut stop = ear;
+
+        while self.nodes[ear].prev != self.nodes[ear].next {
+            let prev = self.nodes[ear].prev;
+            let next = self.nodes[ear].next;
+            let ear_ok = if inv_size != 0.0 {
+                self.is_ear_hashed(ear, min_x, min_y, inv_size)
+            } else {
+                self.is_ear(ear)
+            };
+
+            if ear_ok {
+                self.triangles.push(self.nodes[prev].i as u32);
+                self.triangles.push(self.nodes[ear].i as u32);
+                self.triangles.push(self.nodes[next].i as u32);
+
+                self.remove_node(ear);
+                ear = self.nodes[next].next;
+                stop = ear;
+                continue;
+            }
+
+            ear = next;
+
+            if ear == stop {
+                match pass {
+                    0 => {
+                        let filtered = self.filter_points(Some(ear), None);
+                        self.earcut_linked(filtered, 1, min_x, min_y, inv_size);
+                    }
+                    1 => {
+                        let cured = self.cure_local_intersections(ear);
+                        self.earcut_linked(cured, 2, min_x, min_y, inv_size);
+                    }
+                    2 => self.split_earcut(ear, min_x, min_y, inv_size),
+                    _ => {}
+                }
+                break;
+            }
+        }
+    }
+
+    fn filter_points(&mut self, start: Option<NodeId>, end: Option<NodeId>) -> Option<NodeId> {
+        let mut end = end.unwrap_or(start?);
+        let mut point = start?;
+
+        loop {
+            let mut again = false;
+            let prev = self.nodes[point].prev;
+            let next = self.nodes[point].next;
+
+            if !self.nodes[point].steiner
+                && (self.equals(point, next) || self.area(prev, point, next) == 0.0)
+            {
+                self.remove_node(point);
+                point = prev;
+                end = prev;
+
+                if point == self.nodes[point].next {
+                    break;
+                }
+
+                again = true;
+            } else {
+                point = next;
+            }
+
+            if !again && point == end {
+                break;
+            }
+        }
+
+        Some(end)
+    }
+
+    fn is_ear(&self, ear: NodeId) -> bool {
+        let a = self.nodes[ear].prev;
+        let b = ear;
+        let c = self.nodes[ear].next;
+
+        if self.area(a, b, c) >= 0.0 {
+            return false;
+        }
+
+        let mut point = self.nodes[c].next;
+        while point != a {
+            if self.point_in_triangle(a, b, c, point)
+                && self.area(self.nodes[point].prev, point, self.nodes[point].next) >= 0.0
+            {
+                return false;
+            }
+            point = self.nodes[point].next;
+        }
+
+        true
+    }
+
+    fn is_ear_hashed(&self, ear: NodeId, min_x: f64, min_y: f64, inv_size: f64) -> bool {
+        let a = self.nodes[ear].prev;
+        let b = ear;
+        let c = self.nodes[ear].next;
+
+        if self.area(a, b, c) >= 0.0 {
+            return false;
+        }
+
+        let min_tx = self.nodes[a].x.min(self.nodes[b].x.min(self.nodes[c].x));
+        let min_ty = self.nodes[a].y.min(self.nodes[b].y.min(self.nodes[c].y));
+        let max_tx = self.nodes[a].x.max(self.nodes[b].x.max(self.nodes[c].x));
+        let max_ty = self.nodes[a].y.max(self.nodes[b].y.max(self.nodes[c].y));
+
+        let min_z = z_order(min_tx, min_ty, min_x, min_y, inv_size);
+        let max_z = z_order(max_tx, max_ty, min_x, min_y, inv_size);
+
+        let mut prev_z = self.nodes[ear].prev_z;
+        let mut next_z = self.nodes[ear].next_z;
+
+        while prev_z.is_some()
+            && next_z.is_some()
+            && self.nodes[prev_z.unwrap()].z >= min_z
+            && self.nodes[next_z.unwrap()].z <= max_z
+        {
+            let prev_node = prev_z.unwrap();
+            if prev_node != a
+                && prev_node != c
+                && self.point_in_triangle(a, b, c, prev_node)
+                && self.area(
+                    self.nodes[prev_node].prev,
+                    prev_node,
+                    self.nodes[prev_node].next,
+                ) >= 0.0
+            {
+                return false;
+            }
+            prev_z = self.nodes[prev_node].prev_z;
+
+            let next_node = next_z.unwrap();
+            if next_node != a
+                && next_node != c
+                && self.point_in_triangle(a, b, c, next_node)
+                && self.area(
+                    self.nodes[next_node].prev,
+                    next_node,
+                    self.nodes[next_node].next,
+                ) >= 0.0
+            {
+                return false;
+            }
+            next_z = self.nodes[next_node].next_z;
+        }
+
+        while let Some(prev_node) = prev_z {
+            if self.nodes[prev_node].z < min_z {
+                break;
+            }
+            if prev_node != a
+                && prev_node != c
+                && self.point_in_triangle(a, b, c, prev_node)
+                && self.area(
