    fn filter_points(&mut self, start: Option<NodeId>, end: Option<NodeId>) -> Option<NodeId> {
        let mut end = end.unwrap_or(start?);
        let mut point = start?;

        loop {
            let mut again = false;
            let prev = self.nodes[point].prev;
            let next = self.nodes[point].next;

            if !self.nodes[point].steiner
