                self.remove_node(point);
                point = prev;
                end = prev;

                if point == self.nodes[point].next {
                    break;
                }

                again = true;
            } else {
                point = next;
            }

            if !again && point == end {
                break;
            }
        }

        Some(end)
    }

    fn is_ear(&self, ear: NodeId) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false;
        }

        let mut point = self.nodes[c].next;
        while point != a {
            if self.point_in_triangle(a, b, c, point)
                && self.area(self.nodes[point].prev, point, self.nodes[point].next) >= 0.0
            {
                return false;
            }
            point = self.nodes[point].next;
        }

        true
    }

    fn is_ear_hashed(&self, ear: NodeId, min_x: f64, min_y: f64, inv_size: f64) -> bool {
