        let max_tx = self.nodes[a].x.max(self.nodes[b].x.max(self.nodes[c].x));
        let max_ty = self.nodes[a].y.max(self.nodes[b].y.max(self.nodes[c].y));

        let min_z = z_order(min_tx, min_ty, min_x, min_y, inv_size);
        let max_z = z_order(max_tx, max_ty, min_x, min_y, inv_size);

        let mut prev_z = self.nodes[ear].prev_z;
        let mut next_z = self.nodes[ear].next_z;

        while prev_z.is_some()
            && next_z.is_some()
            && self.nodes[prev_z.unwrap()].z >= min_z
            && self.nodes[next_z.unwrap()].z <= max_z
        {
            let prev_node = prev_z.unwrap();
            if prev_node != a
                && prev_node != c
                && self.point_in_triangle(a, b, c, prev_node)
                && self.area(
                    self.nodes[prev_node].prev,
                    prev_node,
                    self.nodes[prev_node].next,
                ) >= 0.0
            {
                return false;
            }
            prev_z = self.nodes[prev_node].prev_z;

            let next_node = next_z.unwrap();
            if next_node != a
                && next_node != c
                && self.point_in_triangle(a, b, c, next_node)
                && self.area(
                    self.nodes[next_node].prev,
                    next_node,
                    self.nodes[next_node].next,
                ) >= 0.0
            {
                return false;
            }
            next_z = self.nodes[next_node].next_z;
        }

        while let Some(prev_node) = prev_z {
            if self.nodes[prev_node].z < min_z {
                break;
            }
            if prev_node != a
                && prev_node != c
                && self.point_in_triangle(a, b, c, prev_node)
                && self.area(
                    self.nodes[prev_node].prev,
                    prev_node,
                    self.nodes[prev_node].next,
                ) >= 0.0
            {
                return false;
            }
            prev_z = self.nodes[prev_node].prev_z;
        }

        while let Some(next_node) = next_z {
            if self.nodes[next_node].z > max_z {
                break;
            }
            if next_node != a
                && next_node != c
                && self.point_in_triangle(a, b, c, next_node)
                && self.area(
                    self.nodes[next_node].prev,
                    next_node,
                    self.nodes[next_node].next,
                ) >= 0.0
            {
                return false;
            }
            next_z = self.nodes[next_node].next_z;
        }

        true
    }

    fn cure_local_intersections(&mut self, start: NodeId) -> Option<NodeId> {
        let mut start = start;
        let mut point = start;

        loop {
            let a = self.nodes[point].prev;
            let point_next = self.nodes[point].next;
            let b = self.nodes[point_next].next;

            if !self.equals(a, b)
                && self.intersects(a, point, point_next, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
            {
                self.triangles.push(self.nodes[a].i as u32);
                self.triangles.push(self.nodes[point].i as u32);
                self.triangles.push(self.nodes[b].i as u32);

                self.remove_node(point);
                self.remove_node(point_next);

                point = b;
                start = b;
            }

            point = self.nodes[point].next;
            if point == start {
                break;
            }
        }

        self.filter_points(Some(point), None)
    }

    fn split_earcut(&mut self, start: NodeId, min_x: f64, min_y: f64, inv_size: f64) {
        let mut a = start;

        loop {
            let mut b = self.nodes[self.nodes[a].next].next;

            while b != self.nodes[a].prev {
                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
                    let c = self.split_polygon(a, b);
                    let a_filtered = self.filter_points(Some(a), Some(self.nodes[a].next));
                    let c_filtered = self.filter_points(Some(c), Some(self.nodes[c].next));
                    self.earcut_linked(a_filtered, 0, min_x, min_y, inv_size);
                    self.earcut_linked(c_filtered, 0, min_x, min_y, inv_size);
                    return;
                }

                b = self.nodes[b].next;
            }

            a = self.nodes[a].next;
            if a == start {
                break;
            }
        }
    }

    fn split_polygon(&mut self, a: NodeId, b: NodeId) -> NodeId {
        let a2 = self.nodes.len();
        self.nodes.push(Node::new(
            self.nodes[a].i,
            self.nodes[a].x,
            self.nodes[a].y,
            a2,
            a2,
        ));

        let b2 = self.nodes.len();
        self.nodes.push(Node::new(
            self.nodes[b].i,
            self.nodes[b].x,
            self.nodes[b].y,
            b2,
            b2,
        ));

        let an = self.nodes[a].next;
        let bp = self.nodes[b].prev;

        self.nodes[a].next = b;
        self.nodes[b].prev = a;

        self.nodes[a2].next = an;
        self.nodes[a2].prev = b2;
        self.nodes[an].prev = a2;

        self.nodes[b2].next = a2;
        self.nodes[b2].prev = bp;
        self.nodes[bp].next = b2;

        b2
    }

    fn is_valid_diagonal(&self, a: NodeId, b: NodeId) -> bool {
        if self.nodes[self.nodes[a].next].i == self.nodes[b].i
            || self.nodes[self.nodes[a].prev].i == self.nodes[b].i
            || self.intersects_polygon(a, b)
        {
            return false;
        }

        let sectors_non_zero =
            self.area(self.nodes[a].prev, a, self.nodes[b].prev) != 0.0
                || self.area(a, self.nodes[b].prev, b) != 0.0;

        (self.locally_inside(a, b)
            && self.locally_inside(b, a)
            && self.middle_inside(a, b)
            && sectors_non_zero)
            || (self.equals(a, b)
                && self.area(self.nodes[a].prev, a, self.nodes[a].next) > 0.0
                && self.area(self.nodes[b].prev, b, self.nodes[b].next) > 0.0)
    }

    fn intersects_polygon(&self, a: NodeId, b: NodeId) -> bool {
        let mut point = a;

        loop {
            let next = self.nodes[point].next;
            if self.nodes[point].i != self.nodes[a].i
                && self.nodes[next].i != self.nodes[a].i
                && self.nodes[point].i != self.nodes[b].i
                && self.nodes[next].i != self.nodes[b].i
                && self.intersects(point, next, a, b)
            {
                return true;
            }

            point = next;
            if point == a {
                break;
            }
        }

        false
    }

    fn middle_inside(&self, a: NodeId, b: NodeId) -> bool {
        let px = (self.nodes[a].x + self.nodes[b].x) * 0.5;
        let py = (self.nodes[a].y + self.nodes[b].y) * 0.5;
        let mut inside = false;
        let mut point = a;

        loop {
            let next = self.nodes[point].next;
            let point_y = self.nodes[point].y;
            let next_y = self.nodes[next].y;

            if (point_y > py) != (next_y > py)
                && px
                    < (self.nodes[next].x - self.nodes[point].x) * (py - point_y)
                        / (next_y - point_y)
                        + self.nodes[point].x
            {
                inside = !inside;
            }

            point = next;
            if point == a {
                break;
            }
        }

        inside
    }

    fn locally_inside(&self, a: NodeId, b: NodeId) -> bool {
        if self.area(self.nodes[a].prev, a, self.nodes[a].next) < 0.0 {
            self.area(a, b, self.nodes[a].next) >= 0.0
                && self.area(a, self.nodes[a].prev, b) >= 0.0
        } else {
            self.area(a, b, self.nodes[a].prev) < 0.0
                || self.area(a, self.nodes[a].next, b) < 0.0
        }
    }

    fn intersects(&self, p1: NodeId, q1: NodeId, p2: NodeId, q2: NodeId) -> bool {
        if (self.equals(p1, p2) && self.equals(q1, q2))
            || (self.equals(p1, q2) && self.equals(q1, p2))
        {
            return true;
        }

        let o1 = sign(self.area(p1, q1, p2));
        let o2 = sign(self.area(p1, q1, q2));
        let o3 = sign(self.area(p2, q2, p1));
        let o4 = sign(self.area(p2, q2, q1));

        if o1 != o2 && o3 != o4 {
            return true;
        }

        (o1 == 0 && self.on_segment(p1, p2, q1))
            || (o2 == 0 && self.on_segment(p1, q2, q1))
            || (o3 == 0 && self.on_segment(p2, p1, q2))
            || (o4 == 0 && self.on_segment(p2, q1, q2))
    }

    fn on_segment(&self, p: NodeId, q: NodeId, r: NodeId) -> bool {
        self.nodes[q].x >= self.nodes[p].x.min(self.nodes[r].x)
            && self.nodes[q].x <= self.nodes[p].x.max(self.nodes[r].x)
            && self.nodes[q].y >= self.nodes[p].y.min(self.nodes[r].y)
            && self.nodes[q].y <= self.nodes[p].y.max(self.nodes[r].y)
    }

    fn index_curve(&mut self, start: NodeId, min_x: f64, min_y: f64, inv_size: f64) {
        let mut order = Vec::new();
        let mut point = start;

        loop {
            self.nodes[point].z = z_order(self.nodes[point].x, self.nodes[point].y, min_x, min_y, inv_size);
            order.push(point);
            point = self.nodes[point].next;
            if point == start {
                break;
            }
        }

        order.sort_by_key(|node| self.nodes[*node].z);

        for index in 0..order.len() {
            let prev_z = if index == 0 { None } else { Some(order[index - 1]) };
            let next_z = if index + 1 == order.len() {
                None
            } else {
                Some(order[index + 1])
            };

            self.nodes[order[index]].prev_z = prev_z;
            self.nodes[order[index]].next_z = next_z;
        }
    }

    fn point_in_triangle(&self, a: NodeId, b: NodeId, c: NodeId, p: NodeId) -> bool {
        let ax = self.nodes[a].x;
        let ay = self.nodes[a].y;
        let bx = self.nodes[b].x;
        let by = self.nodes[b].y;
        let cx = self.nodes[c].x;
        let cy = self.nodes[c].y;
        let px = self.nodes[p].x;
        let py = self.nodes[p].y;

        (cx - px) * (ay - py) >= (ax - px) * (cy - py)
            && (ax - px) * (by - py) >= (bx - px) * (ay - py)
            && (bx - px) * (cy - py) >= (cx - px) * (by - py)
    }

    fn area(&self, a: NodeId, b: NodeId, c: NodeId) -> f64 {
        (self.nodes[b].y - self.nodes[a].y) * (self.nodes[c].x - self.nodes[b].x)
            - (self.nodes[b].x - self.nodes[a].x) * (self.nodes[c].y - self.nodes[b].y)
    }

    fn equals(&self, a: NodeId, b: NodeId) -> bool {
        self.nodes[a].x == self.nodes[b].x && self.nodes[a].y == self.nodes[b].y
    }
}

fn signed_area(points: &[Point]) -> f64 {
    let mut sum = 0.0;
    let mut previous = points.len() - 1;

    for current in 0..points.len() {
        sum += (points[previous].x - points[current].x) * (points[current].y + points[previous].y);
        previous = current;
    }

    sum
}

fn z_order(x: f64, y: f64, min_x: f64, min_y: f64, inv_size: f64) -> u32 {
    let mut x = (32767.0 * (x - min_x) * inv_size) as u32;
    let mut y = (32767.0 * (y - min_y) * inv_size) as u32;

    x = (x | (x << 8)) & 0x00ff_00ff;
    x = (x | (x << 4)) & 0x0f0f_0f0f;
    x = (x | (x << 2)) & 0x3333_3333;
    x = (x | (x << 1)) & 0x5555_5555;

    y = (y | (y << 8)) & 0x00ff_00ff;
    y = (y | (y << 4)) & 0x0f0f_0f0f;
    y = (y | (y << 2)) & 0x3333_3333;
    y = (y | (y << 1)) & 0x5555_5555;

    x | (y << 1)
}

fn sign(value: f64) -> i8 {
    if value > 0.0 {
        1
    } else if value < 0.0 {
        -1
    } else {
        0
    }
}

